// --- Collision (tested primitive) ------------------------------------------

export function collides(ball, brick) { ... unchanged ... }

// Entry time of the segment [A→B] into `box` (an AABB in ball-CENTER space,
// i.e. the brick already expanded by the ball radius), as a fraction in [0,1].
// Returns null when the segment never enters the box. Slab method.
function sweptEntry(ax, ay, bx, by, box) {
  const dx = bx - ax;
  const dy = by - ay;
  let tmin = 0;
  let tmax = 1;
  let axis = null;   // 'x' | 'y' | null (already inside at start)
  let side = null;   // 'min' | 'max' — which slab produced the entry
  // X slab
  if (Math.abs(dx) < 1e-9) {
    if (ax < box.x || ax > box.x + box.w) return null;
  } else {
    let t1 = (box.x - ax) / dx;
    let t2 = (box.x + box.w - ax) / dx;
    let s1 = 'min', s2 = 'max';
    if (t1 > t2) { const tmp = t1; t1 = t2; t2 = tmp; const stmp = s1; s1 = s2; s2 = stmp; }
    if (t1 > tmin) { tmin = t1; axis = 'x'; side = s1; }
    tmax = Math.min(tmax, t2);
  }
  // Y slab
  if (Math.abs(dy) < 1e-9) {
    if (ay < box.y || ay > box.y + box.h) return null;
  } else {
    let t1 = (box.y - ay) / dy;
    let t2 = (box.y + box.h - ay) / dy;
    let s1 = 'min', s2 = 'max';
    if (t1 > t2) { swap }
    if (t1 > tmin) { tmin = t1; axis = 'y'; side = s1; }
    tmax = Math.min(tmax, t2);
  }
  if (tmin > tmax) return null;
  return { t: tmin, axis, side };
}
```

