export function step(state, dt) {
  const { ball, paddle } = state;
  const prevX = ball.x;
  const prevY = ball.y;

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

  // Side walls
  ... unchanged ...

  // Ceiling
  ... unchanged ...

  // Bricks: continuous (swept) collision, one bounce per step.
  // The grid gap (8 px) is smaller than the ball diameter (14 px), so a ball
  // sitting on a seam overlaps two bricks at once: resolve the single earliest
  // hit and stop, or the second brick would invert the bounce back.
  let best = null;
  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    const box = { x: brick.x - ball.r, y: brick.y - ball.r, w: brick.w + 2 * ball.r, h: brick.h + 2 * ball.r };
    const hit = sweptEntry(prevX, prevY, ball.x, ball.y, box);
    if (!hit || hit.t > 1) continue;
    // penetration at the current position, for the already-overlapping case
    const penX = Math.min(ball.x + ball.r - brick.x, brick.x + brick.w - (ball.x - ball.r));
    const penY = Math.min(ball.y + ball.r - brick.y, brick.y + brick.h - (ball.y - ball.r));
    const pen = Math.min(penX, penY);
    if (!best || hit.t < best.hit.t || (hit.t === best.hit.t && pen < best.pen)) {
      best = { brick, hit, penX, penY, pen };
    }
  }
  if (best) {
    const { brick, hit, penX, penY } = best;
    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);
    bounceOffBrick(ball, brick, hit, penX, penY);
  }

  // Paddle ... swept + static ...
  ...

  // Exit through the bottom
  if (ball.y - ball.r > HEIGHT) return true;
  return false;
}
