// slab method probe — verify entry times for the sonde fixtures
function swept(ax, ay, bx, by, box) {
  const dx = bx - ax, dy = by - ay;
  let tmin = 0, tmax = 1, axis = null, side = null;
  if (Math.abs(dx) < 1e-9) { if (ax < box.x || ax > box.x + box.w) return null; }
  else {
    let t1 = (box.x - ax) / dx, t2 = (box.x + box.w - ax) / dx, s1 = 'min', s2 = 'max';
    if (t1 > t2) { [t1, t2] = [t2, t1]; [s1, s2] = [s2, s1]; }
    if (t1 > tmin) { tmin = t1; axis = 'x'; side = s1; }
    tmax = Math.min(tmax, t2);
  }
  if (Math.abs(dy) < 1e-9) { if (ay < box.y || ay > box.y + box.h) return null; }
  else {
    let t1 = (box.y - ay) / dy, t2 = (box.y + box.h - ay) / dy, s1 = 'min', s2 = 'max';
    if (t1 > t2) { [t1, t2] = [t2, t1]; [s1, s2] = [s2, s1]; }
    if (t1 > tmin) { tmin = t1; axis = 'y'; side = s1; }
    tmax = Math.min(tmax, t2);
  }
  return tmin <= tmax ? { t: tmin, axis, side } : null;
}
