}

// --- Collision (tested primitive) ------------------------------------------

// True if the ball (circle approximated by its box) overlaps the brick.
// Simple AABB test: it only says WHETHER the ball and the brick overlap, not
// WHICH face was hit — the face is resolved by `bounceOffBrick()` in `step()`.
export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

// Continuous collision primitive: entry time of the segment [A → B] into
// `box`, where `box` is the AABB already expanded by the ball radius (i.e.
// ball-center space). Returns `{ t, axis, side }` — t in [0, 1] (0 = already
// overlapping at the start of the step), the axis and the slab ('min'|'max')
// the segment entered through — or null when the segment never touches the
// box. Slab method (Liang–Barsky): a discrete end-position check lets a step
// longer than the obstacle jump over it; sweeping the whole segment does not.
function sweptEntry(ax, ay, bx, by, box) {
  const dx = bx - ax;
  const dy = by - ay;
  let tmin = 0;
  let tmax = 1;
  let axis = null;
  let side = null;

  if (Math.abs(dx) < 1e-9) {
    if (ax < box.x || ax > box.x + box.w) return null;
  } else {
    let t1 = (box.x - ax) / dx;
    let t2 = (box.x + box.w - ax) / dx;
    let s1 = 'min';
    let s2 = 'max';
    if (t1 > t2) {
      [t1, t2] = [t2, t1];
      [s1, s2] = [s2, s1];
    }
    if (t1 > tmin) {
      tmin = t1;
      axis = 'x';
      side = s1;
    }
    tmax = Math.min(tmax, t2);
  }

  if (Math.abs(dy) < 1e-9) {
    if (ay < box.y || ay > box.y + box.h) return null;
  } else {
    let t1 = (box.y - ay) / dy;
    let t2 = (box.y + box.h - ay) / dy;
    let s1 = 'min';
    let s2 = 'max';
    if (t1 > t2) {
      [t1, t2] = [t2, t1];
      [s1, s2] = [s2, s1];
    }
    if (t1 > tmin) {
      tmin = t1;
      axis = 'y';
      side = s1;
    }
    tmax = Math.min(tmax, t2);
  }

  if (tmin > tmax) return null;
  return { t: tmin, axis, side };
}

// Flips the velocity component(s) of the face that was hit and pushes the ball
// back out of the brick. Two situations:
//  - the ball crossed the expanded box during this step (`hit.t > 0`): place
//    it at the entry point and invert the axis it entered through;
//  - the ball was already overlapping (`hit.t === 0`): resolve by the axis of
//    smallest penetration; equal penetrations mean a corner and invert BOTH.
function bounceOffBrick(ball, brick, hit, prevX, prevY, penX, penY) {
  if (hit.t > 0) {
    ball.x = prevX + (ball.x - prevX) * hit.t;
    ball.y = prevY + (ball.y - prevY) * hit.t;
    if (hit.axis === 'x') {
      ball.vx = hit.side === 'min' ? -Math.abs(ball.vx) : Math.abs(ball.vx);
    } else {
      ball.vy = hit.side === 'min' ? -Math.abs(ball.vy) : Math.abs(ball.vy);
    }
    return;
  }

  // Already overlapping: the smallest penetration decides the hit face.
  if (penX < penY) {
    const hitLeft =
      ball.x + ball.r - brick.x < brick.x + brick.w - (ball.x - ball.r);
    ball.vx = hitLeft ? -Math.abs(ball.vx) : Math.abs(ball.vx);
    ball.x = hitLeft ? brick.x - ball.r : brick.x + brick.w + ball.r;
  } else if (penY < penX) {
    const hitTop =
      ball.y + ball.r - brick.y < brick.y + brick.h - (ball.y - ball.r);
    ball.vy = hitTop ? -Math.abs(ball.vy) : Math.abs(ball.vy);
    ball.y = hitTop ? brick.y - ball.r : brick.y + brick.h + ball.r;
  } else {
    // Corner: both components invert, and the ball is pushed out on both axes.
    ball.vx = -ball.vx;
    ball.vy = -ball.vy;
    ball.x += Math.sign(ball.vx) * penX;
    ball.y += Math.sign(ball.vy) * penY;
  }
}

// --- Score & combo (NOT covered by tests — debt #5) ------------------------

// Combo multiplier. UNBOUNDED today: a long combo makes the score blow up
// uncontrollably (see #5, expected improvement = clamp it).
export function comboMultiplier(combo) {
  return 1 + combo * 0.5;
}

// Points earned for breaking a brick, combo included.
export function scoreForBrick(brick, combo) {
  return Math.round(brick.points * comboMultiplier(combo));
}

// --- Best score persistence ------------------------------------------------

// Reads the best score from a localStorage-compatible storage.
// Robust to corrupted or missing storage: returns 0 instead of throwing.
export function loadBest(storage) {
  if (!storage) return 0;
  try {
    const raw = storage.getItem(STORAGE_KEY);
    const value = Number.parseInt(raw, 10);
    return Number.isFinite(value) && value > 0 ? value : 0;
  } catch {
    return 0;
  }
}

// Writes the best score if the current score beats it. Returns the updated best.
export function saveBest(storage, score) {
  const best = loadBest(storage);
  if (score > best && storage) {
    try {
      storage.setItem(STORAGE_KEY, String(score));
    } catch {
      // storage unavailable (private mode, quota): silently ignore
    }
    return score;
  }
  return best;
}

// --- Physics (movement + wall/paddle bounces) ------------------------------

// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls, the bricks and the paddle. Brick collision lives here (moved out
// of `frame()`, debt #2): pure logic, testable without a DOM, and swept so a
// fast ball cannot skip a brick between two samples.
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;

  // Position BEFORE the move: the sweeps below test the whole segment
  // [before → after], not just the after-sample.
  const prevX = ball.x;
  const prevY = ball.y;

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

  // Side walls
  if (ball.x - ball.r < 0) {
    ball.x = ball.r;
    ball.vx = Math.abs(ball.vx);
  } else if (ball.x + ball.r > WIDTH) {
    ball.x = WIDTH - ball.r;
    ball.vx = -Math.abs(ball.vx);
  }


[183 more lines in file. Use offset=280 to continue.]

  // Ceiling
  if (ball.y - ball.r < 0) {
    ball.y = ball.r;
    ball.vy = Math.abs(ball.vy);
  }

  // Bricks — swept, one bounce per step. The grid gap (8 px) is smaller than
  // the ball diameter (14 px), so a ball resting on a seam overlaps two bricks
  // at once: bouncing on each would invert the velocity twice and cancel out.
  // Resolve only the earliest contact of the step (ties: smallest penetration).
  let best = null;
  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    const box = {
      x: brick.x - ball.r,
      y: brick.y - ball.r,
      w: brick.w + 2 * ball.r,
      h: brick.h + 2 * ball.r,
    };
    const hit = sweptEntry(prevX, prevY, ball.x, ball.y, box);
    if (!hit || hit.t > 1) continue;
    const penX = Math.min(
      ball.x + ball.r - brick.x,
      brick.x + brick.w - (ball.x - ball.r),
    );
    const penY = Math.min(
      ball.y + ball.r - brick.y,
      brick.y + brick.h - (ball.y - ball.r),
    );
    const pen = Math.min(penX, penY);
    if (!best || hit.t < best.hit.t || (hit.t === best.hit.t && pen < best.pen)) {
      best = { brick, hit, penX, penY, pen };
    }
  }
  if (best) {
    const { brick, hit, penX, penY } = best;
    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);
    bounceOffBrick(ball, brick, hit, prevX, prevY, penX, penY);
  }

  // Paddle — swept like the bricks: from level 4 the capped frame moves the
  // ball farther than the paddle band, and a discrete end-position check would
  // let it fall through. The horizontal range is the ball-EDGE box, so a ball
  // that only grazes the paddle with its edge still bounces.
  if (ball.vy > 0) {
    const box = {
      x: paddle.x - ball.r,
      y: paddle.y - ball.r,
      w: paddle.w + 2 * ball.r,
      h: paddle.h + 2 * ball.r,
    };
    const hit = sweptEntry(prevX, prevY, ball.x, ball.y, box);
    if (hit !== null) {
      ball.y = paddle.y - ball.r;
      ball.vy = -Math.abs(ball.vy);
      // The rebound angle depends on where the paddle was hit.
      const hitRatio = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
      let vx = ballSpeed(state.level) * 0.6 * hitRatio;
      const vy = -ballSpeed(state.level);
      // Dead angle: a center hit gives hitRatio = 0 and vx = 0, leaving the
      // ball looping vertically forever. Keep a minimum horizontal component.
      const minVx = ballSpeed(state.level) * 0.15;
      if (Math.abs(vx) < minVx) vx = (vx < 0 ? -1 : 1) * minVx;
      // Keep the bounce at the level's speed: rewriting vx alone would change
      // the norm, so the ball would accelerate with every paddle touch.
      const norm = Math.hypot(vx, vy);
      ball.vx = (vx / norm) * ballSpeed(state.level);
      ball.vy = (vy / norm) * ballSpeed(state.level);
      state.combo = 0; // touching the paddle resets the combo
    }
  }

  // Exit through the bottom: ball lost
  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}

// --- Rendering (DOM): brick collision logic STILL mixed in here ------------

// Main render loop. Rendering only: brick collision, bounce and scoring moved
// to `step()` (debt #2 resolved) so the behavior is pure logic, testable
// without a DOM and independent of the draw pass.
export function frame(ctx, state) {
  // Background
  ctx.fillStyle = palette.background;
  ctx.fillRect(0, 0, WIDTH, HEIGHT);

  // Bricks: draw the survivors only.
  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    ctx.fillStyle = brickColor(brick.row);
    ctx.fillRect(brick.x, brick.y, brick.w, brick.h);
  }

  // Paddle — color hard-coded instead of using the palette (inconsistency #6).
  ctx.fillStyle = '#00e5ff';
  ctx.fillRect(state.paddle.x, state.paddle.y, state.paddle.w, state.paddle.h);

  // Ball — also hard-coded (#6).
  ctx.fillStyle = '#39ff14';
  ctx.beginPath();
  ctx.arc(state.ball.x, state.ball.y, state.ball.r, 0, Math.PI * 2);
  ctx.fill();

  // HUD
  ctx.fillStyle = palette.text;
  ctx.font = '16px monospace';
  ctx.fillText(`Score ${state.score}`, 12, 24);
  ctx.fillText(`Best ${state.best}`, WIDTH - 110, 24);
  ctx.fillText(`Lives ${state.lives}`, WIDTH / 2 - 30, 24);
}

// --- Boot (browser entry point) --------------------------------------------

// Starts the game: wires up the canvas, the mouse and the animation loop.
// The only function that depends on the DOM; never called on import.
export function boot(doc = document) {
  const canvas = doc.getElementById('game');
  const ctx = canvas.getContext('2d');
  canvas.width = WIDTH;
  canvas.height = HEIGHT;

  const state = createState(1);
  state.best = loadBest(doc.defaultView?.localStorage ?? globalThis.localStorage);
  state.running = true;

  // Glow pass: a coarse offscreen light map, stretched over the field.
  const offscreen = doc.createElement('canvas');
  offscreen.width = GLOW_W;
  offscreen.height = GLOW_H;
  const glow = {
    map: createGlowMap(),
    image: offscreen.getContext('2d').createImageData(GLOW_W, GLOW_H),
  };

  // Move the paddle with the mouse.
  canvas.addEventListener('mousemove', (e) => {
    const rect = canvas.getBoundingClientRect();
    const x = e.clientX - rect.left - state.paddle.w / 2;
    state.paddle.x = Math.max(0, Math.min(WIDTH - state.paddle.w, x));
  });

  let last = performance.now();
  function loop(now) {
    const dt = Math.min((now - last) / 1000, 0.05);
    last = now;

    if (state.running) {
      const lost = step(state, dt);
      if (lost) {
        state.lives -= 1;
        state.combo = 0;
        if (state.lives <= 0) {
          state.best = saveBest(globalThis.localStorage, state.score);
          Object.assign(state, createState(state.level));
          state.best = loadBest(globalThis.localStorage);
        } else {
          // relaunch the ball
          state.ball = createState(state.level).ball;
        }
      }

      // Level cleared: all bricks broken
      if (state.bricks.every((b) => !b.alive)) {
        state.level += 1;
        state.bricks = makeBricks(state.level);
        state.ball = createState(state.level).ball;
      }
    }

    frame(ctx, state);
    drawGlow(ctx, glow, state, WIDTH, HEIGHT, offscreen);
    requestAnimationFrame(loop);
  }
  requestAnimationFrame(loop);

  return state;
}

